CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(20) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('super_admin','operations','dispatcher','clerk','agent','finance','boarding','passenger') NOT NULL DEFAULT 'passenger',active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS permissions(role VARCHAR(30) NOT NULL,permission VARCHAR(60) NOT NULL,PRIMARY KEY(role,permission));
CREATE TABLE IF NOT EXISTS login_attempts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,bucket CHAR(64) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(bucket,created_at));
CREATE TABLE IF NOT EXISTS password_resets(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,used_at DATETIME NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS routes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,distance_km INT UNSIGNED NOT NULL DEFAULT 0,duration_minutes INT UNSIGNED NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS stops(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,route_id BIGINT UNSIGNED NOT NULL,position INT UNSIGNED NOT NULL,town VARCHAR(100) NOT NULL,terminal VARCHAR(180) NOT NULL,minutes_from_start INT UNSIGNED NOT NULL,UNIQUE(route_id,position),FOREIGN KEY(route_id) REFERENCES routes(id));
CREATE TABLE IF NOT EXISTS fares(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,route_id BIGINT UNSIGNED NOT NULL,origin_position INT UNSIGNED NOT NULL,destination_position INT UNSIGNED NOT NULL,seat_class VARCHAR(30) NOT NULL DEFAULT 'standard',amount_cents BIGINT UNSIGNED NOT NULL,UNIQUE(route_id,origin_position,destination_position,seat_class),CHECK(destination_position>origin_position),FOREIGN KEY(route_id,origin_position) REFERENCES stops(route_id,position),FOREIGN KEY(route_id,destination_position) REFERENCES stops(route_id,position));
CREATE TABLE IF NOT EXISTS buses(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,registration VARCHAR(30) NOT NULL UNIQUE,model VARCHAR(100) NOT NULL,amenities VARCHAR(255) NOT NULL DEFAULT '',status ENUM('available','maintenance','retired') NOT NULL DEFAULT 'available');
CREATE TABLE IF NOT EXISTS layouts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,bus_id BIGINT UNSIGNED NOT NULL,version INT UNSIGNED NOT NULL,UNIQUE(bus_id,version),FOREIGN KEY(bus_id) REFERENCES buses(id));
CREATE TABLE IF NOT EXISTS layout_seats(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,layout_id BIGINT UNSIGNED NOT NULL,label VARCHAR(12) NOT NULL,deck INT UNSIGNED NOT NULL DEFAULT 1,seat_row INT UNSIGNED NOT NULL,column_number INT UNSIGNED NOT NULL,seat_class VARCHAR(30) NOT NULL DEFAULT 'standard',blocked BOOLEAN NOT NULL DEFAULT FALSE,UNIQUE(layout_id,label),UNIQUE(layout_id,deck,seat_row,column_number),FOREIGN KEY(layout_id) REFERENCES layouts(id));
CREATE TABLE IF NOT EXISTS crew(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,phone VARCHAR(20) NOT NULL,job VARCHAR(50) NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS trips(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,route_id BIGINT UNSIGNED NOT NULL,bus_id BIGINT UNSIGNED NOT NULL,departure_at DATETIME NOT NULL,arrival_at DATETIME NOT NULL,sales_close_at DATETIME NOT NULL,status ENUM('scheduled','boarding','departed','completed','delayed','cancelled') NOT NULL DEFAULT 'scheduled',layout_version INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(departure_at,status),FOREIGN KEY(route_id) REFERENCES routes(id),FOREIGN KEY(bus_id) REFERENCES buses(id),CHECK(arrival_at>departure_at));
CREATE TABLE IF NOT EXISTS trip_crew(trip_id BIGINT UNSIGNED NOT NULL,crew_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(trip_id,crew_id),FOREIGN KEY(trip_id) REFERENCES trips(id),FOREIGN KEY(crew_id) REFERENCES crew(id));
CREATE TABLE IF NOT EXISTS trip_stops(trip_id BIGINT UNSIGNED NOT NULL,position INT UNSIGNED NOT NULL,town VARCHAR(100) NOT NULL,terminal VARCHAR(180) NOT NULL,scheduled_at DATETIME NOT NULL,PRIMARY KEY(trip_id,position),FOREIGN KEY(trip_id) REFERENCES trips(id));
CREATE TABLE IF NOT EXISTS trip_seats(trip_id BIGINT UNSIGNED NOT NULL,label VARCHAR(12) NOT NULL,deck INT UNSIGNED NOT NULL,seat_row INT UNSIGNED NOT NULL,column_number INT UNSIGNED NOT NULL,seat_class VARCHAR(30) NOT NULL,blocked BOOLEAN NOT NULL DEFAULT FALSE,PRIMARY KEY(trip_id,label),UNIQUE(trip_id,deck,seat_row,column_number),FOREIGN KEY(trip_id) REFERENCES trips(id));
CREATE TABLE IF NOT EXISTS bookings(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reference VARCHAR(40) NOT NULL UNIQUE,access_hash CHAR(64) NOT NULL UNIQUE,user_id BIGINT UNSIGNED NULL,trip_id BIGINT UNSIGNED NOT NULL,origin_position INT UNSIGNED NOT NULL,destination_position INT UNSIGNED NOT NULL,contact_name VARCHAR(120) NOT NULL,contact_phone VARCHAR(20) NOT NULL,contact_email VARCHAR(190) NOT NULL,status ENUM('held','expired','confirmed','cancelled','resolution','rescheduled') NOT NULL DEFAULT 'held',payment_status ENUM('unpaid','paid','partial','refund_pending','refunded') NOT NULL DEFAULT 'unpaid',hold_expires_at DATETIME NOT NULL,total_cents BIGINT UNSIGNED NOT NULL,paid_cents BIGINT UNSIGNED NOT NULL DEFAULT 0,fare_snapshot JSON NOT NULL,policy_snapshot JSON NOT NULL,channel ENUM('web','counter','agent') NOT NULL DEFAULT 'web',sold_by BIGINT UNSIGNED NULL,replacement_for BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(trip_id,status,hold_expires_at),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(trip_id,origin_position) REFERENCES trip_stops(trip_id,position),FOREIGN KEY(trip_id,destination_position) REFERENCES trip_stops(trip_id,position),FOREIGN KEY(sold_by) REFERENCES users(id),FOREIGN KEY(replacement_for) REFERENCES bookings(id),CHECK(destination_position>origin_position));
CREATE TABLE IF NOT EXISTS passengers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,booking_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,seat_label VARCHAR(12) NOT NULL,boarding_status ENUM('not_boarded','boarded','no_show') NOT NULL DEFAULT 'not_boarded',UNIQUE(booking_id,seat_label),FOREIGN KEY(booking_id) REFERENCES bookings(id));
CREATE TABLE IF NOT EXISTS segment_allocations(trip_id BIGINT UNSIGNED NOT NULL,seat_label VARCHAR(12) NOT NULL,segment_position INT UNSIGNED NOT NULL,booking_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(trip_id,seat_label,segment_position),FOREIGN KEY(trip_id,seat_label) REFERENCES trip_seats(trip_id,label),FOREIGN KEY(trip_id,segment_position) REFERENCES trip_stops(trip_id,position),FOREIGN KEY(booking_id) REFERENCES bookings(id),INDEX(booking_id));
CREATE TABLE IF NOT EXISTS payments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,booking_id BIGINT UNSIGNED NOT NULL,provider VARCHAR(30) NOT NULL,provider_reference VARCHAR(100) NOT NULL,amount_cents BIGINT UNSIGNED NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'KES',recorded_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(provider,provider_reference),FOREIGN KEY(booking_id) REFERENCES bookings(id),FOREIGN KEY(recorded_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS resolution_cases(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,booking_id BIGINT UNSIGNED NOT NULL,payment_id BIGINT UNSIGNED NULL,reason VARCHAR(255) NOT NULL,status ENUM('open','resolved') NOT NULL DEFAULT 'open',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(payment_id),FOREIGN KEY(booking_id) REFERENCES bookings(id),FOREIGN KEY(payment_id) REFERENCES payments(id));
CREATE TABLE IF NOT EXISTS tickets(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,passenger_id BIGINT UNSIGNED NOT NULL UNIQUE,token_hash CHAR(64) NOT NULL UNIQUE,token_value VARCHAR(100) NOT NULL UNIQUE,status ENUM('valid','cancelled','boarded','no_show') NOT NULL DEFAULT 'valid',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(passenger_id) REFERENCES passengers(id));
CREATE TABLE IF NOT EXISTS boarding_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ticket_id BIGINT UNSIGNED NOT NULL UNIQUE,actor_id BIGINT UNSIGNED NOT NULL,trip_id BIGINT UNSIGNED NOT NULL,stop_position INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(ticket_id) REFERENCES tickets(id),FOREIGN KEY(actor_id) REFERENCES users(id),FOREIGN KEY(trip_id,stop_position) REFERENCES trip_stops(trip_id,position));
CREATE TABLE IF NOT EXISTS refunds(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,booking_id BIGINT UNSIGNED NOT NULL UNIQUE,amount_cents BIGINT UNSIGNED NOT NULL,fee_cents BIGINT UNSIGNED NOT NULL,status ENUM('requested','approved','processing','completed','rejected') NOT NULL DEFAULT 'requested',requested_by BIGINT UNSIGNED NULL,approved_by BIGINT UNSIGNED NULL,processed_by BIGINT UNSIGNED NULL,provider_reference VARCHAR(100) NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(booking_id) REFERENCES bookings(id),FOREIGN KEY(requested_by) REFERENCES users(id),FOREIGN KEY(approved_by) REFERENCES users(id),FOREIGN KEY(processed_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS jobs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,dedupe_key VARCHAR(190) NOT NULL UNIQUE,kind VARCHAR(40) NOT NULL,payload JSON NOT NULL,status ENUM('pending','processing','done','failed') NOT NULL DEFAULT 'pending',attempts INT UNSIGNED NOT NULL DEFAULT 0,available_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,locked_at DATETIME NULL,last_error VARCHAR(200),INDEX(status,available_at));
CREATE TABLE IF NOT EXISTS notifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,job_id BIGINT UNSIGNED NOT NULL UNIQUE,booking_id BIGINT UNSIGNED NOT NULL,message TEXT NOT NULL,delivery_mode VARCHAR(20) NOT NULL DEFAULT 'local_log',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(job_id) REFERENCES jobs(id),FOREIGN KEY(booking_id) REFERENCES bookings(id));
CREATE TABLE IF NOT EXISTS audit_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,actor_id BIGINT UNSIGNED NULL,action VARCHAR(80) NOT NULL,entity_type VARCHAR(50) NOT NULL,entity_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS settings(name VARCHAR(80) PRIMARY KEY,value TEXT NOT NULL);
